import { expect, test, uniqueName } from "../../fixtures";

test.describe("manage vendors", () => {
  test(
    "the same vendor name is allowed in a different tenant",
    { tag: "@VEN-04" },
    async ({ apiAs }) => {
      // Arrange: a vendor with the same name already exists in another tenant.
      // A unique name keeps this run isolated from other tests sharing the database.
      const name = uniqueName("Acme Freight");
      const globex = await apiAs("otherTenant");
      const existing = await globex.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: "ops@globex-freight.example",
        },
      });
      expect(existing.status()).toBe(201);

      // Act: the signed-in Northwind member creates a vendor with that same name.
      const member = await apiAs("member");
      const response = await member.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });

      // Assert
      expect(response.status()).toBe(201);
      const vendor = await response.json();
      expect(vendor.name).toBe(name);
      expect(vendor.id).not.toBe((await existing.json()).id);
    },
  );
});
